namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public required string Code { get; set; }
    public required string Title { get; set; }
    public required string Description { get; set; }
    public int Credits { get; set; }
    public required string Schedule { get; set; }
    public required string InstructorName { get; set; }
    public required string InstructorBio { get; set; }
    public int DepartmentId { get; set; }
    public bool IsFeatured { get; set; }
}

public class Department
{
    public int Id { get; set; }
    public required string Name { get; set; }
    public required string Abbreviation { get; set; }
}

public class EnrollmentRequest
{
    public string StudentName { get; set; } = string.Empty;
    public string StudentId { get; set; } = string.Empty;
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments =
    [
        new() { Id = 1, Name = "Computer Science", Abbreviation = "CS" },
        new() { Id = 2, Name = "Mathematics", Abbreviation = "MATH" },
        new() { Id = 3, Name = "Physics", Abbreviation = "PHYS" },
        new() { Id = 4, Name = "English", Abbreviation = "ENG" },
        new() { Id = 5, Name = "History", Abbreviation = "HIST" },
    ];

    private readonly List<Course> _courses =
    [
        new() { Id = 1, Code = "CS 101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using C#. Topics include variables, control flow, data structures, and object-oriented principles.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and computer science education. She holds a PhD from MIT and has published extensively on programming pedagogy.", DepartmentId = 1, IsFeatured = true },
        new() { Id = 2, Code = "CS 201", Title = "Data Structures and Algorithms", Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs) and algorithm design techniques (sorting, searching, dynamic programming).", Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", InstructorName = "Dr. James Park", InstructorBio = "Dr. Park specializes in algorithm optimization and competitive programming. He previously worked at Google Research before joining academia.", DepartmentId = 1, IsFeatured = true },
        new() { Id = 3, Code = "CS 310", Title = "Database Systems", Description = "Introduction to relational database design, SQL, normalization, indexing, and transaction management. Includes hands-on projects with PostgreSQL.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", InstructorName = "Dr. Maria Santos", InstructorBio = "Dr. Santos brings a decade of industry experience in database architecture from her time at Oracle and Amazon.", DepartmentId = 1 },
        new() { Id = 4, Code = "MATH 151", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Robert Liu", InstructorBio = "Dr. Liu is a renowned mathematician with research interests in analysis and mathematical modeling. He has taught calculus for over 20 years.", DepartmentId = 2, IsFeatured = true },
        new() { Id = 5, Code = "MATH 250", Title = "Linear Algebra", Description = "Vector spaces, matrices, determinants, eigenvalues, and linear transformations with applications to data science.", Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", InstructorName = "Dr. Elena Volkov", InstructorBio = "Dr. Volkov's research focuses on computational linear algebra and its applications in machine learning.", DepartmentId = 2 },
        new() { Id = 6, Code = "MATH 320", Title = "Probability and Statistics", Description = "Probability theory, random variables, distributions, hypothesis testing, and regression analysis.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", InstructorName = "Dr. Robert Liu", InstructorBio = "Dr. Liu is a renowned mathematician with research interests in analysis and mathematical modeling. He has taught calculus for over 20 years.", DepartmentId = 2 },
        new() { Id = 7, Code = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Emphasis on problem-solving and laboratory work.", Credits = 4, Schedule = "Tue/Thu 9:00–10:20 AM + Lab Fri 1:00–3:00 PM", InstructorName = "Dr. Alan Foster", InstructorBio = "Dr. Foster is an experimental physicist who previously conducted research at CERN. He is passionate about making physics accessible.", DepartmentId = 3, IsFeatured = true },
        new() { Id = 8, Code = "PHYS 205", Title = "Electromagnetism", Description = "Electric and magnetic fields, Maxwell's equations, electromagnetic waves, and optics.", Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM + Lab Tue 3:00–5:00 PM", InstructorName = "Dr. Priya Sharma", InstructorBio = "Dr. Sharma specializes in condensed matter physics and has received multiple teaching excellence awards.", DepartmentId = 3 },
        new() { Id = 9, Code = "ENG 110", Title = "Academic Writing", Description = "Develop college-level writing skills through essay composition, research methods, and critical analysis of texts.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Prof. David Miller", InstructorBio = "Prof. Miller is a published author and writing instructor with expertise in rhetoric and composition studies.", DepartmentId = 4 },
        new() { Id = 10, Code = "ENG 225", Title = "American Literature", Description = "Survey of American literature from the colonial period to the present, examining major works and literary movements.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM", InstructorName = "Dr. Catherine Brooks", InstructorBio = "Dr. Brooks specializes in 20th-century American fiction and has published three books on modernist literature.", DepartmentId = 4 },
        new() { Id = 11, Code = "HIST 101", Title = "World History I", Description = "Survey of world civilizations from ancient times through the Renaissance, covering political, social, and cultural developments.", Credits = 3, Schedule = "Tue/Thu 2:00–3:20 PM", InstructorName = "Dr. Michael Okafor", InstructorBio = "Dr. Okafor is a historian of global connections with fieldwork experience across three continents.", DepartmentId = 5 },
        new() { Id = 12, Code = "HIST 240", Title = "Modern European History", Description = "European history from the Enlightenment to the present day, including revolutions, world wars, and the formation of the EU.", Credits = 3, Schedule = "Mon/Wed 3:30–4:50 PM", InstructorName = "Dr. Anna Weber", InstructorBio = "Dr. Weber holds a joint appointment with the European Studies program and has authored numerous articles on 20th-century European politics.", DepartmentId = 5 },
    ];

    private readonly List<EnrollmentRequest> _enrollments = [];

    public IReadOnlyList<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public IReadOnlyList<Course> GetCourses(string? search = null, int? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public IReadOnlyList<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public void SubmitEnrollment(EnrollmentRequest request)
    {
        _enrollments.Add(request);
    }
}

